const cloudcraftCustomScopes={
  'Architecture validation':{meaning:'An independent review of a proposed or existing cloud architecture before implementation.',activities:['Confirm business, security, availability, recovery and operational requirements','Review diagrams, service choices, dependencies, identity, networking, security and operability','Assess the design against agreed provider guidance and customer constraints','Record gaps, risks, decisions and prioritized recommendations'],outputs:['Architecture assessment report','Reviewed or updated high-level architecture diagram','Risk, assumption and decision register','Prioritized remediation or implementation roadmap'],customer:['Provide current diagrams, requirements, policies and stakeholder access','Identify business-critical workloads, compliance obligations, RTO/RPO and budget constraints','Review findings and approve architecture decisions'],boundary:'Implementation, detailed low-level design, penetration testing, compliance certification and remediation are excluded unless separately scoped.',sow:['Cloud platform and environments in scope','Number and type of workloads','Review domains and required standards','Workshop and stakeholder schedule','Required document depth and acceptance criteria']},
  'Infrastructure as code':{meaning:'Creates reusable, version-controlled cloud infrastructure templates for an agreed platform scope.',activities:['Define repository, module, naming and environment structure','Build the agreed Terraform, Bicep or CloudFormation components','Configure remote state, variable handling, review controls and documented deployment steps','Test repeatable deployment in the agreed non-production environment'],outputs:['Version-controlled infrastructure code','Reusable modules and environment configuration','State-management and deployment design','Test evidence, README and operator handover'],customer:['Provide repository and cloud-access prerequisites','Approve coding, security and naming standards','Supply required variables, certificates, secrets interfaces and test environment'],boundary:'Application code, third-party licences, unmanaged secrets, production deployment and every future cloud service are excluded unless listed in the SOW.',sow:['Cloud provider and exact resources','Environments and regions','Module count and reuse requirements','CI/CD platform and repository','Testing, documentation and code-acceptance criteria']},
  'Deployment automation':{meaning:'Automates repeatable infrastructure or application deployment steps through an agreed delivery pipeline.',activities:['Map the current build, approval, release and rollback process','Design and configure pipeline stages, gates and environment promotion','Integrate agreed code repository, artefact source, identity and secrets interfaces','Test deployment, failure handling and rollback workflow'],outputs:['Configured deployment pipeline','Pipeline definition and supporting scripts','Deployment and rollback runbook','Test evidence and administrator handover'],customer:['Provide repositories, runners, service connections and environment access','Approve release gates, segregation of duties and change controls','Provide deployable artefacts and nominated test owners'],boundary:'Application remediation, software licences, bespoke product engineering and unlimited pipeline variants are excluded unless expressly scoped.',sow:['Pipeline platform and deployment targets','Applications or infrastructure components','Environment and stage count','Approval, security and rollback controls','Test scenarios and acceptance criteria']},
  'Deployment verification':{meaning:'Validates that an implemented cloud environment matches the approved design and agreed acceptance requirements.',activities:['Create a verification plan mapped to design and acceptance criteria','Inspect deployed configuration, connectivity, identity, security and observability','Execute agreed functional and operational-readiness checks','Record evidence, exceptions and remediation recommendations'],outputs:['Verification plan and completed checklist','Configuration and test evidence','Defect and exception register','Acceptance recommendation and handover report'],customer:['Provide the approved design, build records and test access','Make application owners available for functional validation','Own remediation unless it is separately included'],boundary:'Remediation, performance/load testing, penetration testing, certification and ongoing monitoring are excluded unless explicitly included.',sow:['Environment and components to verify','Approved design baseline','Required test domains and evidence format','Severity and exception process','Acceptance authority and completion criteria']},
  'Migration or deployment project':{meaning:'A separately scoped project to migrate workloads or deploy a defined cloud solution from planning through handover.',activities:['Perform discovery, dependency and readiness assessment','Create the implementation or migration design, plan, runbook and rollback controls','Execute the agreed deployment or migration waves','Validate the outcome, manage exceptions and complete operational handover'],outputs:['Detailed project design and delivery plan','Runbook, rollback plan and schedule','Implemented or migrated scoped workloads','Validation evidence, exception record and handover documentation'],customer:['Provide source and target access, owners, licences and change approvals','Resolve source-data or application defects unless included','Coordinate business testing, downtime approval and acceptance'],boundary:'Scope is limited to the workloads, data, integrations, waves and stabilization period named in the SOW; licensing, consumption and unrelated remediation are excluded.',sow:['Source and target platforms','Workload, user, data and integration quantities','Downtime, sequencing and rollback requirements','Tooling and third-party responsibilities','Testing, hypercare, schedule and acceptance criteria']}
};
const landingZoneModulesMarkup=`<section class="scope-group conditional hidden" data-conditional="cloudcraftModel:landing-zone"><div class="scope-group-title"><h3>Landing Zone Modules</h3><span>Modular one-time pricing</span></div><div class="landing-zone-base"><span>Required foundation</span><strong>Base Landing Zone</strong><small>AWS organization or Azure tenant hierarchy, shared platform accounts/subscriptions and the first workload environment.</small><b data-landing-zone-base>${moneyOption('NE0-023-001')}</b></div><div class="landing-zone-modules">${landingZoneModuleIds.map(id=>`<label><input type="checkbox" name="landingZoneModule" value="${id}"><span><strong>${rowById(id).service}</strong><small>${landingZoneDescriptions[id]}</small><b>${moneyOption(id)}</b></span></label>`).join('')}</div></section>`;

