function updateCloudcraftScope(){const form=document.querySelector('[data-scope="cloudcraft"]'),title=document.getElementById('cloudcraftScopeTitle'),content=document.getElementById('cloudcraftScopeContent');if(!form||!title||!content)return;const model=value(form,'cloudcraftModel');if(model==='custom'){const focus=value(form,'cloudcraftFocus'),scope=cloudcraftCustomScopes[focus];title.textContent=focus?`${focus} SOW baseline`:'Custom CloudCraft SOW baseline';if(!scope){content.className='implementation-scope-empty';content.textContent='Select a custom implementation focus to see the proposed SOW activities, deliverables, customer responsibilities, exclusions and required scope parameters.';return}content.className='implementation-scope-content';content.innerHTML=sowColumns(scope);return}if(model==='landing-zone'){const platform=value(form,'cloudcraftPlatform')||'AWS or Azure',moduleIds=[...form.querySelectorAll('[name="landingZoneModule"]:checked')].map(input=>input.value),spokes=numberValue(form,'cloudcraftSpokes'),moduleNames=moduleIds.map(id=>rowById(id)?.service).filter(Boolean);title.textContent=`${platform} Landing Zone SOW baseline`;const platformFoundation=platform==='AWS'?'AWS Organizations, Control Tower and organizational-unit hierarchy; shared Management, Log Archive and Audit accounts; one workload account with VPC and DNS baseline.':platform==='Azure'?'Tenant and management-group hierarchy; Management, Connectivity and Identity subscriptions; one application subscription with VNet and DNS baseline.':'The selected AWS organization or Azure tenant hierarchy, shared platform accounts or subscriptions, and one initial workload environment.';const scope={meaning:`Establishes a governed ${platform} cloud foundation into which application workloads can be deployed. The required base covers ${platformFoundation}`,activities:['Confirm organization, ownership, region, naming, tagging and operating-model decisions','Build the agreed hierarchy, shared platform areas and first workload environment','Configure the baseline network and DNS foundation','Validate the foundation and conduct administrator handover',...(moduleNames.length?[`Implement the selected modules: ${moduleNames.join(', ')}`]:[]),...(spokes?[`Build ${spokes} additional VPC / VNet spoke${spokes===1?'':'s'} with agreed routing and security controls`]:[])],outputs:['Landing-zone architecture and decision record','Configured cloud hierarchy and shared platform foundation','First workload environment with network and DNS baseline',...(moduleNames.length?['Configuration and evidence for each selected module']:[]),'Validation evidence and operational handover documentation'],customer:['Provide a suitable cloud tenant or organization and authorized administrative access','Nominate platform, identity, network, security, finance and operations decision owners','Provide domains, IP ranges, identity-provider details, security requirements and billing ownership','Review design decisions, attend validation and approve acceptance'],boundary:'Workload migration, application deployment, cloud consumption, licences, carrier or circuit charges, third-party products and ongoing managed operations are excluded unless separately selected and written into the SOW.',sow:['AWS or Azure, tenant or organization and target regions','Account or subscription hierarchy and quantity','Network topology, CIDRs, DNS, connectivity and spoke count','Selected modules, integrations and control baseline','Infrastructure-as-code ownership and repository','Testing, documentation, schedule and acceptance authority']};content.className='implementation-scope-content';content.innerHTML=sowColumns(scope);return}title.textContent='SOW scope baseline';content.className='implementation-scope-empty';content.textContent='Select a pricing route and service focus to see the proposed SOW activities, deliverables, customer responsibilities, exclusions and required scope parameters.'}
